codeExamples.code:
-- MySQL 8.0.18+ : tree format with actual time and rows
EXPLAIN ANALYZE
SELECT * FROM orders WHERE customer_id = 42;
/* -> Index lookup on orders using idx_orders_customer
      (cost=4.2 rows=12) (actual time=0.03..0.05 rows=12 loops=1) */

-- MySQL estimate-only structured output
EXPLAIN FORMAT=JSON SELECT * FROM orders WHERE customer_id = 42;

-- SQL Server : measured timing + logical/physical reads
SET STATISTICS TIME ON;
SET STATISTICS IO ON;
SELECT * FROM dbo.orders WHERE customer_id = 42;
-- Plus: include the Actual Execution Plan (Ctrl+M) for actual rows/loops
/* Table 'orders'. Scan count 1, logical reads 4, physical reads 0
   CPU time = 0 ms, elapsed time = 1 ms */
